def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            q=[(r,c)];seen.add((r,c));cells=[]
            while q:
                y,x=q.pop();cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                        seen.add((yy,xx));q.append((yy,xx))
            r0=min(y for y,x in cells);c0=min(x for y,x in cells)
            objects.append((color,r0,c0,{(y-r0,x-c0) for y,x in cells}))
    out=[[0]*w for _ in range(h)]
    # Upper-region motifs gather at the top; lower-region motifs gather at bottom.
    for color,r,c,shape in objects:
        bottom=r >= h//2
        dr=(h-1-max(dy for dy,dx in shape)-r) if bottom else -r
        for dy,dx in shape:
            yy=r+dr+dy
            if 0<=yy<h and 0<=c+dx<w: out[yy][c+dx]=color
    return out

